        A = [[0 if u != v else -len(G[u]) + sum(1 for w in G[v] if w != u) for v in range(n)] for u in range(n)]
        eigenvector = power_iteration(A)
        lambda_2 = max(sum(A[i][j] * eigenvector[j] for j in range(n)) * eigenvector[i] for i in range(n))
        return lambda_2

