    n = len(L)
    det = matrix_determinant(L, mod)
    if det == 0:
        return 0
    prime1 = 293
    prime2 = 2017
    det1 = matrix_determinant(matrix_mod(L, prime1), prime1)
    det2 = matrix_determinant(matrix_mod(L, prime2), prime2)
    det = (det1 * pow(prime1, mod - 2, mod) + det2 * pow(prime2, mod - 2, mod)) % mod
    return det

